typedef struct {
    int u, v;
    double w;
} Edge;

typedef struct {
    double x, y;
} Point;

int parent[10001];
int rank[10001];

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void unite(int x, int y) {
    int rx = find(x), ry = find(y);
    if (rx == ry) return;
    if (rank[rx] < rank[ry])
        parent[rx] = ry;
    else if (rank[rx] > rank[ry])
        parent[ry] = rx;
    else {
        parent[ry] = rx;
        rank[rx]++;
    }
}

int cmp(const void *a, const void *b) {
    Edge *ea = (Edge*)a;
    Edge *eb = (Edge*)b;
    if (ea->w < eb->w) return -1;
    if (ea->w > eb->w) return 1;
    return 0;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    Point piles[10001];
    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &piles[i].x, &piles[i].y);
    }

    Edge edges[500000];
    double total_len = 0.0;

    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        u--; v--;
        double dx = piles[u].x - piles[v].x;
        double dy = piles[u].y - piles[v].y;
        double w = sqrt(dx*dx + dy*dy);
        edges[i].u = u;
        edges[i].v = v;
        edges[i].w = w;
        total_len += w;
    }

    qsort(edges, M, sizeof(Edge), cmp);

    for (int i = 0; i < N; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    double mst_len = 0.0;
    int count = 0;
    for (int i = 0; i < M && count < N-1; i++) {
        if (find(edges[i].u) != find(edges[i].v)) {
            unite(edges[i].u, edges[i].v);
            mst_len += edges[i].w;
            count++;
        }
    }

    printf("%.6f\n", total_len - mst_len);

    return 0;
}

