public class SaveCats {
    static class Point {
        int x, y;
        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static class Edge implements Comparable<Edge> {
        int u, v;
        double length;
        Edge(int u, int v, double length) {
            this.u = u;
            this.v = v;
            this.length = length;
        }
        public int compareTo(Edge other) {
            return Double.compare(this.length, other.length);
        }
    }

    static int[] parent;
    static int[] rank;

    static int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    static boolean union(int x, int y) {
        int rx = find(x);
        int ry = find(y);
        if (rx == ry) return false;
        if (rank[rx] < rank[ry]) {
            parent[rx] = ry;
        } else if (rank[rx] > rank[ry]) {
            parent[ry] = rx;
        } else {
            parent[ry] = rx;
            rank[rx]++;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int N = Integer.parseInt(firstLine[0]);
        int M = Integer.parseInt(firstLine[1]);

        Point[] piles = new Point[N];
        for (int i = 0; i < N; i++) {
            String[] coords = br.readLine().split(" ");
            int x = Integer.parseInt(coords[0]);
            int y = Integer.parseInt(coords[1]);
            piles[i] = new Point(x, y);
        }

        List<Edge> edges = new ArrayList<>();
        double totalLength = 0.0;

        for (int i = 0; i < M; i++) {
            String[] parts = br.readLine().split(" ");
            int u = Integer.parseInt(parts[0]) - 1;
            int v = Integer.parseInt(parts[1]) - 1;
            double dx = piles[u].x - piles[v].x;
            double dy = piles[u].y - piles[v].y;
            double len = Math.sqrt(dx * dx + dy * dy);
            edges.add(new Edge(u, v, len));
            totalLength += len;
        }

        parent = new int[N];
        rank = new int[N];
        for (int i = 0; i < N; i++) {
            parent[i] = i;
            rank[i] = 0;
        }

        Collections.sort(edges);
        double mstLength = 0.0;
        for (Edge e : edges) {
            if (union(e.u, e.v)) {
                mstLength += e.length;
            }
        }

        double result = totalLength - mstLength;
        System.out.printf("%.10f%n", result);
    }
}

