public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        long[] X = new long[N], Y = new long[N];
        for (int i = 0; i < N; i++) { X[i] = sc.nextLong(); Y[i] = sc.nextLong(); }

        Map<String, List<long[]>> lineMap = new HashMap<>();

        for (int i = 0; i < M; i++) {
            int a = sc.nextInt()-1, b = sc.nextInt()-1;
            long x1=X[a],y1=Y[a],x2=X[b],y2=Y[b];
            long dx=x2-x1, dy=y2-y1;
            long A=dy, B=-dx, C=dx*y1-dy*x1;
            long g = gcd(gcd(Math.abs(A),Math.abs(B)),Math.abs(C));
            if(g>0){A/=g;B/=g;C/=g;}
            if(A<0||(A==0&&B<0)){A=-A;B=-B;C=-C;}
            String key = A+","+B+","+C;
            lineMap.computeIfAbsent(key, k->new ArrayList<>()).add(new long[]{x1,y1,x2,y2});
        }

        double total = 0;
        for (Map.Entry<String,List<long[]>> e : lineMap.entrySet()) {
            List<long[]> segs = e.getValue();
            long[] s0 = segs.get(0);
            long dx=s0[2]-s0[0], dy=s0[3]-s0[1];
            List<double[]> intervals = new ArrayList<>();
            for (long[] s : segs) {
                double t1 = (dx!=0)?(s[0]-s0[0])/(double)dx:(s[1]-s0[1])/(double)dy;
                double t2 = (dx!=0)?(s[2]-s0[0])/(double)dx:(s[3]-s0[1])/(double)dy;
                if(t1>t2){double tmp=t1;t1=t2;t2=tmp;}
                intervals.add(new double[]{t1,t2});
            }
            intervals.sort((a,b)->Double.compare(a[0],b[0]));
            double len = Math.sqrt(dx*dx+dy*dy);
            double start=intervals.get(0)[0], end=intervals.get(0)[1];
            for(double[] iv:intervals){if(iv[0]<=end)end=Math.max(end,iv[1]);else{total+=( end-start)*len;start=iv[0];end=iv[1];}}
            total+=(end-start)*len;
        }
        System.out.printf("%.2f%n", total);
    }
    static long gcd(long a,long b){return b==0?a:gcd(b,a%b);}
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);
        int m = fs.nextInt();

        double[] x = new double[n + 1];
        double[] y = new double[n + 1];

        for (int i = 1; i <= n; i++) {
            x[i] = fs.nextDouble();
            y[i] = fs.nextDouble();
        }

        double total = 0.0;
        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            double dx = x[a] - x[b];
            double dy = y[a] - y[b];
            total += Math.hypot(dx, dy);
        }

        System.out.printf(Locale.US, "%.2f%n", total);
    }
